head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
    var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
    var r = d(id); if (r) return r;
    var s = dd(P + id); r = d(s); if (r) return r;
    var g = s.indexOf('G_');
    if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
    return d(s.replace(P, ''));
};
scwin.tr1_onclick = function(e) {
    tabcontrol.setSelectedTabIndex(1);
    alert("2번째 탭으로 이동확인.");
};
scwin.tr2_onclick = function(e) {
    tabcontrol.setSelectedTabIndex("tabs2");
    //alert("ID값을 호출해도 인덱스로 먹히는지 확인한다.");	
};
scwin.tabs1_onclick = function() {
    alert("333");
};
scwin.__hasClass = function(id, className) {
    var classList = scwin.__getDom($p.id + id).className;
    return classList.indexOf(className) >= 0;
}
scwin.__isEnableContent = function(id) {
    var el = scwin.__getDom($p.id + id);
    return el.style.display == "block";
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
}
